import { setAudioModeAsync, useAudioPlayer } from 'expo-audio';
import { useEffect, useRef, useState } from 'react';
import { Button, ScrollView, StyleSheet, Text, View } from 'react-native';
import { activeLineAt, scoreLineChanges, type LineChange } from '../core/timing';
import { DEMO_LINES } from '../data/demoSong';

// Generated by scripts/generate-test-audio.mjs.
// eslint-disable-next-line @typescript-eslint/no-require-imports
const audioSource: number = require('../../assets/r1-test.wav');
const UPDATE_MS = 50;

export function R1SyncScreen() {
  const player = useAudioPlayer(audioSource, { updateInterval: UPDATE_MS });
  const lastIndex = useRef(-1);
  const changes = useRef<LineChange[]>([]);
  const [activeIndex, setActiveIndex] = useState(-1);
  const [positionMs, setPositionMs] = useState(0);
  const [changeCount, setChangeCount] = useState(0);

  useEffect(() => {
    setAudioModeAsync({ playsInSilentMode: true }).catch(() => undefined);
    const subscription = player.addListener('playbackStatusUpdate', (status) => {
      const observedMs = status.currentTime * 1000;
      const index = activeLineAt(observedMs, DEMO_LINES);
      setPositionMs(observedMs);
      setActiveIndex(index);
      if (index > lastIndex.current) {
        for (let next = lastIndex.current + 1; next <= index; next += 1) {
          const line = DEMO_LINES[next];
          if (line) changes.current.push({ lineIndex: next, mappedMs: line.startMs, observedMs });
        }
        lastIndex.current = index;
        setChangeCount(changes.current.length);
      }
    });
    return () => subscription.remove();
  }, [player]);

  async function restart() {
    player.pause();
    await player.seekTo(0);
    lastIndex.current = -1;
    changes.current = [];
    setChangeCount(0);
    player.play();
  }

  const result = scoreLineChanges(changes.current);
  const complete = changeCount === DEMO_LINES.length;

  return (
    <View style={styles.page}>
      <Text style={styles.heading}>R1 · lyric sync on a phone</Text>
      <Text>Expo Audio reports every {UPDATE_MS} ms. Each line change is compared with its map time.</Text>
      <Text style={styles.metric}>
        {(positionMs / 1000).toFixed(2)} s · {changeCount}/{DEMO_LINES.length} changes ·{' '}
        {(result.rate * 100).toFixed(0)}% within 0.5 s
      </Text>
      <Text style={complete && result.passed ? styles.pass : styles.pending}>
        {complete ? (result.passed ? 'PASS (target: at least 95%)' : 'FAIL (target: at least 95%)') : 'Run the full 30-second track for a result'}
      </Text>
      <View style={styles.buttons}>
        <Button title="Play from start" onPress={restart} />
        <Button title="Pause" onPress={() => player.pause()} />
      </View>
      <ScrollView style={styles.lines}>
        {DEMO_LINES.map((line, index) => (
          <Text key={line.startMs} style={[styles.line, index === activeIndex && styles.activeLine]}>
            {(line.startMs / 1000).toFixed(1)}s  {line.text}
          </Text>
        ))}
      </ScrollView>
    </View>
  );
}

const styles = StyleSheet.create({
  page: { flex: 1, gap: 8 },
  heading: { fontSize: 19, fontWeight: '700' },
  metric: { fontWeight: '600' },
  pass: { color: '#087830', fontWeight: '700' },
  pending: { color: '#885d00' },
  buttons: { flexDirection: 'row', gap: 8 },
  lines: { marginTop: 4 },
  line: { padding: 5, fontSize: 16, color: '#777' },
  activeLine: { color: '#000', backgroundColor: '#fff09b', fontWeight: '700' },
});
